let particles = [];
let numParticles = 450;
let tunnelW = 580;
let tunnelH = 380;
let zFar = -1000;
let zNear = 300;
let blackHoleRad = 65;

class TunnelParticle {
  constructor() {
    this.reset(true);
  }

  reset(randomZ = false) {
    this.wall = int(random(4));
    this.u = random(-1.0, 1.0);
    this.z = randomZ ? random(zFar, zNear) : zFar;
    this.speed = random(5.5, 11.5);

    // 變種特點: 烈焰霓虹橙與極光紅
    let colors = [
      [15, 95, 95],    // Orange-red
      [30, 95, 95],    // Orange
      [0, 95, 95],     // Red
      [45, 95, 95],    // Amber-yellow
      [350, 95, 95]    // Hot pink-red
    ];
    this.color = random(colors);

    this.w = random(10, 24);
    this.h = random(14, 38);
  }

  update() {
    let speedFactor = 1.0 + (window.audioLow || 0.5) * 1.5 + (window.beatEnergy || 0.0) * 3.5;
    let weightScale = (window.storyboardWeight !== undefined) ? (window.storyboardWeight / 50.0) : 1.0;
    this.z += this.speed * speedFactor * weightScale;
    if (this.z > zNear) {
      this.reset(false);
    }
  }

  draw() {
    push();
    let x = 0;
    let y = 0;
    let rotX = 0;
    let rotY = 0;

    if (this.wall === 0) {
      x = -tunnelW / 2;
      y = this.u * (tunnelH / 2);
      rotY = HALF_PI;
    } else if (this.wall === 1) {
      x = tunnelW / 2;
      y = this.u * (tunnelH / 2);
      rotY = -HALF_PI;
    } else if (this.wall === 2) {
      x = this.u * (tunnelW / 2);
      y = -tunnelH / 2;
      rotX = HALF_PI;
    } else if (this.wall === 3) {
      x = this.u * (tunnelW / 2);
      y = tunnelH / 2;
      rotX = -HALF_PI;
    }

    // 變種特點: 模擬重力透鏡扭曲，離黑洞越近 (Z 越遠) 且重拍越強，粒子旋轉偏折越劇烈
    let beatVal = window.beatEnergy || 0.0;
    let distToFar = map(this.z, zFar, zNear, 1.0, 0.0); // 1.0 (far end) to 0.0 (near)
    let r_polar = sqrt(x * x + y * y);
    if (r_polar > 0) {
      let theta = atan2(y, x);
      // Lensing bend
      theta += 0.85 * distToFar * beatVal * sin(frameCount * 0.02 + r_polar * 0.01);
      x = r_polar * cos(theta);
      y = r_polar * sin(theta);
    }

    translate(x, y, this.z);
    rotateX(rotX);
    rotateY(rotY);

    colorMode(HSB, 360, 100, 100, 1.0);
    let h = this.color[0];
    let s = this.color[1];
    let b = this.color[2];

    if (window.currentChordColor) {
      let chordC = color(window.currentChordColor);
      let chordH = hue(chordC);
      h = lerp(h, chordH, 0.35);
    }

    let alpha = 1.0;
    if (this.z > 150) {
      alpha = map(this.z, 150, zNear, 1.0, 0.0);
    } else if (this.z < -800) {
      alpha = map(this.z, zFar, -800, 0.0, 1.0);
    }

    fill(h, s, b, alpha);
    noStroke();
    rectMode(CENTER);
    rect(0, 0, this.w, this.h);
    pop();
  }
}

function setup() {
  createCanvas(1280, 720, WEBGL);
  colorMode(HSB, 360, 100, 100, 1.0);
  for (let i = 0; i < numParticles; i++) {
    particles.push(new TunnelParticle());
  }
  background(4, 2, 2);
}

function draw() {
  push();
  resetMatrix();
  noStroke();
  colorMode(RGB, 255, 255, 255, 1.0);
  fill(4, 2, 2, 0.16); // 稍微長一點的拖影
  rect(-width/2, -height/2, width, height);
  pop();

  let beatVal = window.beatEnergy || 0.0;
  let rotZ = sin(frameCount * 0.005) * 0.04;
  let rotY = cos(frameCount * 0.004) * 0.03;
  let rotX = sin(frameCount * 0.003) * 0.02;
  let shake = beatVal * 0.015;

  // 變種特點: 重拍時相機 Zoom 會產生高速微震波 (Gravity Wave)
  let gravityWave = sin(frameCount * 0.6) * beatVal * 0.09;
  let camZoom = 1.0 + (window.audioLow || 0.5) * 0.12 + beatVal * 0.22 + gravityWave;
  let storyboardScale = (window.storyboardWeight !== undefined) ? (window.storyboardWeight / 50.0) : 1.0;

  push();
  scale(camZoom * storyboardScale);
  rotateX(rotX + random(-shake, shake));
  rotateY(rotY + random(-shake, shake));
  rotateZ(rotZ + random(-shake, shake));

  // 1. 繪製引導線
  strokeWeight(0.8);
  stroke(18, 92, 95, 0.12);
  line(-tunnelW/2, -tunnelH/2, zFar, -tunnelW/2, -tunnelH/2, zNear);
  line(tunnelW/2, -tunnelH/2, zFar, tunnelW/2, -tunnelH/2, zNear);
  line(-tunnelW/2, tunnelH/2, zFar, -tunnelW/2, tunnelH/2, zNear);
  line(tunnelW/2, tunnelH/2, zFar, tunnelW/2, tunnelH/2, zNear);

  // 2. 星冕
  push();
  translate(0, 0, zFar + 5);
  let midVal = window.audioMid || 0.5;
  let numLayers = 35;
  let baseHue = 18; // 變種為橘紅火球色
  if (window.currentChordColor) {
    let chordC = color(window.currentChordColor);
    baseHue = hue(chordC);
  }

  let dRad = blackHoleRad + beatVal * 18;
  for (let i = 0; i < numLayers; i++) {
    let rad = dRad * (1.08 + i * 0.09 + beatVal * 0.18);
    let alpha = map(i, 0, numLayers, 0.26, 0.0);
    let hueVal = (baseHue + sin(frameCount * 0.02 + i * 0.14) * 20) % 360;
    noFill();
    stroke(hueVal, 95, 95, alpha);
    strokeWeight(3.5 + i * 0.35 + midVal * 4.0);
    ellipse(0, 0, rad * 2, rad * 2);
  }
  pop();

  // 3. 發光十字
  push();
  translate(0, 0, zFar + 8);
  let crossHue = 18;
  if (window.currentChordColor) {
    let chordC = color(window.currentChordColor);
    crossHue = hue(chordC);
  }
  for (let w = 16; w >= 1.5; w -= 2.0) {
    let alpha = map(w, 1.5, 16, 0.38, 0.02);
    stroke(crossHue, 95, 100, alpha);
    strokeWeight(w + (window.audioHigh || 0.5) * 5.5);
    line(-1000, 0, 1000, 0);
    line(0, -800, 0, 800);
  }
  pop();

  // 4. 事件視界黑洞
  push();
  translate(0, 0, zFar + 10);
  fill(0, 0, 0, 1.0);
  noStroke();
  ellipse(0, 0, dRad * 2, dRad * 2);
  pop();

  // 5. 繪製粒子
  for (let p of particles) {
    p.update();
    p.draw();
  }

  pop();
}

